fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, 320);
        host::display::state_set(2, 0);
        host::display::state_set(3, 320);
        host::display::state_set(4, 0);
        host::display::state_set(5, 0);
    }
    let mut ya: i32 = host::display::state_get(1);
    let mut va: i32 = host::display::state_get(2);
    let mut yb: i32 = host::display::state_get(3);
    let mut vb: i32 = host::display::state_get(4);
    let mut pause: i32 = host::display::state_get(5);
    let floor: i32 = (h - 30) * 8;
    if pause > 0 {
        pause = pause - 1;
        if pause == 0 {
            ya = 320;
            va = 0;
            yb = 320;
            vb = 0;
        }
    } else {
        va = va + 6;
        vb = vb + 6 - vb / 16;
        ya = ya + va;
        yb = yb + vb;
        if ya > floor { ya = floor; va = 0; }
        if yb > floor { yb = floor; vb = 0; }
        if ya == floor && yb == floor {
            pause = 50;
        }
    }
    host::display::state_set(1, ya);
    host::display::state_set(2, va);
    host::display::state_set(3, yb);
    host::display::state_set(4, vb);
    host::display::state_set(5, pause);
    host::display::clear(0x0c0c10);
    host::display::fill_rect(w / 2 - 1, 0, 2, h, 0x242430);
    let mut gy: i32 = 40;
    while gy < h - 20 {
        host::display::fill_rect(0, gy, 8, 1, 0x303040);
        host::display::fill_rect(w - 8, gy, 8, 1, 0x303040);
        gy = gy + 60;
    }
    host::display::fill_rect(0, h - 22, w, 4, 0x404048);
    host::display::fill_rect(w / 4 - 10, ya / 8, 20, 20, 0xf0f0f0);
    host::display::fill_rect(w * 3 / 4 - 10, yb / 8, 20, 20, 0x40c0d0);
    host::display::draw_string(w / 4 - 40, 8, "VACUUM", 0x808080, 1);
    host::display::draw_number(w / 4 + 30, 8, va / 8, 0xffffff, 1);
    host::display::draw_string(w * 3 / 4 - 30, 8, "DRAG", 0x808080, 1);
    host::display::draw_number(w * 3 / 4 + 30, 8, vb / 8, 0xffffff, 1);
    host::display::present();
}
